 let close_steps=plans.iter().enumerate().map(|(i,p)|{let id=quote::format_ident!("Field{}",i);let field=&p.ident;let ty=&p.field_ty;quote!(#active::#id{child,pending,remove}=>{if *remove{let turn=unsafe{self.partial.remove_field::<#ty>(std::mem::offset_of!(#frame,#field),&mut pending.value,0,effect)};if pending.value.is_some(){self.placed-=1;*remove=false;}return #o::settle(effect,#o::closing(#o::physical(#v::RetainedWorkPoll::Complete(turn))))}if !child.terminal_is_empty(){let poll=child.close_step(&mut effect.nested(#o::child_grant(grant)));return #o::settle(effect,poll)}if !pending.terminal_is_empty(){return pending.close_step(effect)}return #o::local_close(effect,d,||{self.active=#active::None;Ok(())})})}).collect::<Vec<_>>();
